import{_ as r,o,c as a,a2 as e}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Провайдеры поиска","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/providers/web-search.md","filePath":"ru/integrations/providers/web-search.md","lastUpdated":1792323081000}'),i={name:"ru/integrations/providers/web-search.md"};function n(l,t,s,d,h,g){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="проваидеры-поиска" tabindex="-1">Провайдеры поиска <a class="header-anchor" href="#проваидеры-поиска" aria-label="Permalink to &quot;Провайдеры поиска&quot;">​</a></h1><p>Memoh позволяет подключить Bot к различным поисковым системам, чтобы он мог искать в вебе актуальную информацию и внешние знания.</p><h2 id="идея-знания-в-реальном-времени" tabindex="-1">Идея: знания в реальном времени <a class="header-anchor" href="#идея-знания-в-реальном-времени" aria-label="Permalink to &quot;Идея: знания в реальном времени&quot;">​</a></h2><p><strong>Search Provider</strong> (провайдер поиска) — это подключение к конкретному поисковому API (например, Brave, Google или Bing). После настройки он становится инструментом, которым Bot может пользоваться в разговоре.</p><hr><h2 id="поддерживаемые-поисковые-системы" tabindex="-1">Поддерживаемые поисковые системы <a class="header-anchor" href="#поддерживаемые-поисковые-системы" aria-label="Permalink to &quot;Поддерживаемые поисковые системы&quot;">​</a></h2><p>Поисковые системы настраиваются на странице <strong>Search Provider</strong> в боковой панели.</p><table tabindex="0"><thead><tr><th>Поддерживаемые системы</th><th>Примечания</th></tr></thead><tbody><tr><td><strong>Brave</strong></td><td>Настоятельно рекомендуется за приватность и производительность.</td></tr><tr><td><strong>Bing</strong></td><td>Индекс Microsoft; широкий глобальный охват.</td></tr><tr><td><strong>Google</strong></td><td>Всеобъемлющий веб-поиск.</td></tr><tr><td><strong>Tavily</strong></td><td>Создан специально для исследований с участием ИИ.</td></tr><tr><td><strong>SearxNG</strong></td><td>Подключение к собственному самостоятельно развёрнутому агрегатору поиска.</td></tr><tr><td><strong>DuckDuckGo</strong></td><td>Поиск с упором на приватность.</td></tr><tr><td><strong>Другие провайдеры</strong></td><td>Sogou, Serper, Jina, Exa, Bocha, Yandex.</td></tr></tbody></table><hr><h2 id="порядок-настроики" tabindex="-1">Порядок настройки <a class="header-anchor" href="#порядок-настроики" aria-label="Permalink to &quot;Порядок настройки&quot;">​</a></h2><h3 id="_1-добавление-проваидера-поиска" tabindex="-1">1. Добавление провайдера поиска <a class="header-anchor" href="#_1-добавление-проваидера-поиска" aria-label="Permalink to &quot;1. Добавление провайдера поиска&quot;">​</a></h3><ol><li>Перейдите на страницу <strong>Search Provider</strong> в боковой панели.</li><li>Нажмите <strong>Add Search Provider</strong>.</li><li>Заполните поля: <ul><li><strong>Name</strong>: удобное имя (например, «My Brave Search»).</li><li><strong>API Key</strong>: ваши учётные данные для API конкретной поисковой системы.</li><li><strong>Другие параметры</strong>: в зависимости от системы могут понадобиться дополнительные настройки (например, <code>base_url</code> для SearxNG).</li></ul></li></ol><h3 id="_2-управление-проваидерами" tabindex="-1">2. Управление провайдерами <a class="header-anchor" href="#_2-управление-проваидерами" aria-label="Permalink to &quot;2. Управление провайдерами&quot;">​</a></h3><ul><li><strong>Edit</strong>: выберите провайдер в боковой панели и обновите его конфигурацию в форме справа.</li><li><strong>Delete</strong>: кнопка <strong>Delete Provider</strong> в форме настроек провайдера.</li></ul><hr><h2 id="назначение-проваидера-поиска-bot" tabindex="-1">Назначение провайдера поиска Bot <a class="header-anchor" href="#назначение-проваидера-поиска-bot" aria-label="Permalink to &quot;Назначение провайдера поиска Bot&quot;">​</a></h2><ol><li>Перейдите на страницу <strong>Bots</strong> и выберите своего Bot.</li><li>Откройте вкладку <strong>General</strong>.</li><li>Найдите выпадающий список <strong>Search Provider</strong> и выберите созданный провайдер.</li><li>Нажмите <strong>Save</strong>.</li></ol><hr><h2 id="взаимодеиствие-с-bot" tabindex="-1">Взаимодействие с Bot <a class="header-anchor" href="#взаимодеиствие-с-bot" aria-label="Permalink to &quot;Взаимодействие с Bot&quot;">​</a></h2><ul><li>Когда вопрос пользователя требует актуальной информации, Bot автоматически вызывает назначенный ему <strong>Search Provider</strong>.</li><li>Bot обрабатывает результаты поиска, чтобы дать обоснованный и точный ответ.</li><li>Несколько результатов поиска могут объединяться в один исчерпывающий ответ.</li></ul>',20)])])}const b=r(i,[["render",n]]);export{u as __pageData,b as default};
